{
  "name": "Odin探测器采集系统",
  "name_en": "Odin detector acquisition system",
  "manufacturer": "",
  "description": "用于实验中高速探测器数据读出与写入的采集系统，负责接收探测器输出并将连续帧写入数据流或文件，常见于同步辐射、成像和其他高通量测量场景。",
  "description_en": "A data acquisition and writing system for high-speed detectors, used to receive detector output and write sequential frames to data streams or files. It is commonly used in synchrotron, imaging, and other high-throughput measurement setups.",
  "tag_hints": [
    "area detector readout",
    "high-rate data acquisition",
    "frame writing",
    "streaming detector data",
    "synchrotron imaging"
  ],
  "actions": [
    {
      "action_name": "auto-observe_indices_written",
      "description": "观察已写入的数据帧索引。",
      "description_en": "Observe the indices of data frames that have been written."
    },
    {
      "action_name": "auto-get_indices_written",
      "description": "获取已写入的数据帧索引。",
      "description_en": "Get the indices of data frames that have been written."
    },
    {
      "action_name": "auto-collect_stream_docs",
      "description": "收集探测器数据流的文档和元数据。",
      "description_en": "Collect stream documents and metadata for the detector data output."
    }
  ]
}

